pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address attacker = address(0x1234);
        vm.deal(attacker, 1 ether);
        uint initialBalance = address(c).balance;
        vm.prank(attacker);
        (bool success, ) = address(c).call{value: 0.5 ether}(abi.encodeWithSignature("sendMoney(address,uint256)", address(0), 0));
        if (success) {
            // Buggy version: non-owner called sendMoney and it succeeded; contract balance increased by 0.5 ether
            assertTrue(address(c).balance == initialBalance + 0.5 ether);
        } else {
            // Correct version: revert; balance unchanged
            assertTrue(address(c).balance == initialBalance);
        }
    }
}

