// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address nonOwner = address(0x123);
        vm.deal(nonOwner, 1 ether);

        uint depositsBefore = c.depositsCount();
        uint contractBalanceBefore = address(c).balance;

        vm.prank(nonOwner);
        (bool success, ) = address(c).call{value: 1 wei}(abi.encodeWithSignature("sendMoney(address,uint256)", address(c), 0));

        uint depositsAfter = c.depositsCount();
        uint contractBalanceAfter = address(c).balance;

        // Reference reverts (deposits unchanged, contract balance unchanged); buggy succeeds (deposits increments, balance increases by 1 wei)
        assertTrue(depositsBefore == depositsAfter && contractBalanceBefore == contractBalanceAfter, "Bug detected: non-owner sendMoney changed state");
    }
}
